            name="name"
            value={formData.name}
            onChange={handleChange}
            required
            placeholder="John Doe"
          />

          <CheckoutFormGroup
            label="Email Address"
            name="email"
            type="email"
            value={formData.email}
            onChange={handleChange}
            required
            placeholder="john@example.com"
          />

          <CheckoutFormGroup
            label="Shipping Address"
            name="address"
            value={formData.address}
            onChange={handleChange}
            required
            placeholder="123 Nebula St"
          />

          <div className="space-y-4">
            <CheckoutFormGroup
              label="Card Number"
              name="card"
              value={formData.card}
              onChange={handleChange}
              required
              placeholder="0000 0000 0000 0000"
            />

            <div className="grid grid-cols-2 gap-4">
              <CheckoutFormGroup
                label="Expiry"
                name="expiry"
                value={formData.expiry}
                onChange={handleChange}
                required
                placeholder="MM/YY"
              />
              <CheckoutFormGroup
                label="CVC"
                name="cvc"
                value={formData.cvc}
                onChange={handleChange}
                required
                placeholder="123"
              />
