            className="w-full mt-6 bg-gradient-to-r from-primary to-secondary hover:from-primary/90 hover:to-secondary/90 text-white font-bold py-4 rounded-xl shadow-glow transition-all active:scale-95"
          >
            Pay ${total.toFixed(2)}
          </button>
        </form>
      </div>
    </motion.div>
  );
};

